    m = re.search(r'tau(\d+)', eid)
    if m:
        raw_val = m.group(1)
        # tau020 -> 0.20, tau025 -> 0.25, etc.
        return int(raw_val) / 100.0 if len(raw_val) >= 2 else int(raw_val) / 10.0
    # Try metrics
    metrics = exp.get('metrics', {})
    if 'tau' in metrics:
        return metrics['tau']
    # Try command
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--conformal_threshold\s+([\d.]+)', cmd)
    if m:
        return float(m.group(1))
    return None

