    m = re.search(r'--K\s+(\d+)', cmd)
    if m:
        return int(m.group(1))
    metrics = exp.get('metrics', {})
    if 'K' in metrics:
        return metrics['K']
    for k in ['k5','k10','k20']:
        if k in eid.lower():
            return int(k[1:])
    return None

def get_sr(exp):
    """Return overall_sr or success_rate (normalized to 0-100)"""
    metrics = exp.get('metrics', {})
    if 'overall_sr' in metrics:
        v = metrics['overall_sr']
        return v if v > 1 else v * 100
    if 'success_rate' in metrics:
        v = metrics['success_rate']
        return v if v > 1 else v * 100
    return None

def get_trigger_rate(exp):
