import json, re
from collections import defaultdict

filepath = "/home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement/042e79d2-e7fb-49bd-a50f-1a95ac9bcf0f/tool-results/mcp-agent-ml-research-read_registry-1779953725470.txt"

with open(filepath, 'r') as f:
    raw = json.load(f)

inner = json.loads(raw['result'])
experiments = inner['data']['experiments']

def parse_sr(v):
    if v is None:
        return None
    if isinstance(v, (int, float)):
        return float(v) if float(v) > 1 else float(v) * 100
    if isinstance(v, str):
        # "19.0% (19/100)" -> 19.0
        m = re.match(r'([\d.]+)%', v)
        if m:
            return float(m.group(1))
        try:
            return float(v)
        except:
            return None
    return None

def get_seed(eid, exp):
    m = re.search(r'-s(\d+)', eid)
    if m:
        return int(m.group(1))
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--seed\s+(\d+)', cmd)
    if m:
        return int(m.group(1))
    return None

def get_tau(eid, exp):
    # From exp_id: tau020 -> 0.20
    m = re.search(r'tau(\d+)', eid.lower())
    if m:
        raw_val = m.group(1)
        return int(raw_val) / 100.0
    metrics = exp.get('metrics', {})
    if 'tau' in metrics:
        return metrics['tau']
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--conformal_threshold\s+([\d.]+)', cmd)
    if m:
        return float(m.group(1))
    return None

def get_mode(eid, exp):
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--mode\s+(\S+)', cmd)
    if m:
        return m.group(1)
    metrics = exp.get('metrics', {})
    if 'mode' in metrics:
        return metrics['mode']
    return None

def get_benchmark(eid, exp):
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--benchmark\s+(\S+)', cmd)
    if m:
        return m.group(1)
    metrics = exp.get('metrics', {})
    if 'benchmark' in metrics:
        return metrics['benchmark']
    for b in ['goal', 'long', 'object', 'spatial']:
        if f'-{b}-' in eid.lower() or eid.lower().endswith(f'-{b}') or f'-{b}' in eid.lower():
            return b
    return None

def get_model(eid, exp):
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--model\s+(\S+)', cmd)
    if m:
        return m.group(1)
    if 'pi05' in eid.lower():
        return 'pi05'
    if 'smolvla' in eid.lower():
        return 'smolvla'
    return None

def get_K(eid, exp):
    cmd = exp.get('spec', {}).get('command', '')
    m = re.search(r'--K\s+(\d+)', cmd)
    if m:
        return int(m.group(1))
    metrics = exp.get('metrics', {})
    if 'K' in metrics:
        return metrics['K']
    m = re.search(r'-k(\d+)-', eid.lower())
    if m:
        return int(m.group(1))
    return None

def get_sr(exp):
    metrics = exp.get('metrics', {})
    if 'overall_sr' in metrics:
        return parse_sr(metrics['overall_sr'])
    if 'success_rate' in metrics:
        return parse_sr(metrics['success_rate'])
    return None

def get_trigger_rate(exp):
    metrics = exp.get('metrics', {})
    return metrics.get('trigger_rate', None)

def make_record(eid, exp):
    metrics = exp.get('metrics', {})
    return {
        'exp_id': eid,
        'benchmark': get_benchmark(eid, exp),
        'mode': get_mode(eid, exp),
        'model': get_model(eid, exp),
        'seed': get_seed(eid, exp),
        'K': get_K(eid, exp),
        'tau': get_tau(eid, exp),
        'overall_sr': get_sr(exp),
        'trigger_rate': get_trigger_rate(exp),
        'per_task': metrics.get('per_task', None),
        'metrics_raw': metrics,
    }

cats = {
    'A_tau': [],
    'B_supp': [],
    'C_pi05_cross': [],
    'D_ksweep': [],
    'E_crm_always_on': [],
    'F_other': []
}

for eid, exp in experiments.items():
    el = eid.lower()
    record = make_record(eid, exp)

    is_crm_always = 'crm-always-on' in el or 'always-on' in el or 'always_on' in el
    is_tau = 'tau' in el and not is_crm_always
    is_supp = 'supp' in el
    is_pi05 = 'pi05' in el
    is_ksweep = bool(re.search(r'ksweep|-k5-|-k10-|-k20-|k5-|k10-|k20-', el)) and not is_supp

    if is_supp:
        cats['B_supp'].append(record)
    elif is_crm_always:
        cats['E_crm_always_on'].append(record)
    elif is_tau:
        cats['A_tau'].append(record)
    elif is_ksweep:
        cats['D_ksweep'].append(record)
    elif is_pi05:
        cats['C_pi05_cross'].append(record)
    else:
        cats['F_other'].append(record)

for cat, recs in cats.items():
    print(f"{cat}: {len(recs)} experiments")

# Save for next steps
import pickle
with open('/tmp/categorized_experiments.pkl', 'wb') as f:
    pickle.dump(cats, f)

